          _ => const <String, dynamic>{},
        },
        ...switch (switchTab) {
          SdkPresent<BetaBrowserSwitchTabConfig?>(value: final value) => {
              'switch_tab': value?.toJson(),
            },
          _ => const <String, dynamic>{},
        },
        ...switch (tripleClick) {
          SdkPresent<BetaBrowserTripleClickConfig?>(value: final value) => {
              'triple_click': value?.toJson(),
            },
          _ => const <String, dynamic>{},
        },
        ...switch (type_) {
          SdkPresent<BetaBrowserTypeConfig?>(value: final value) => {
              'type': value?.toJson(),
            },
          _ => const <String, dynamic>{},
        },
        ...switch (wait) {
          SdkPresent<BetaBrowserWaitConfig?>(value: final value) => {
              'wait': value?.toJson(),
            },
          _ => const <String, dynamic>{},
        },
        ...switch (zoom) {
          SdkPresent<BetaBrowserZoomConfig?>(value: final value) => {
              'zoom': value?.toJson(),
            },
          _ => const <String, dynamic>{},
        },
      };
}
